-- ── story 6-1c: password reset and login rate limits ─────────────────────
-- Generated by drizzle-kit (the `password_resets` table and its two indexes —
-- made IF NOT EXISTS by hand, the 6-2a lint) and hand-amended below the
-- marker: the two CHECKs, RLS on `password_resets`, the two vocabulary CHECKs
-- re-added, and the post-migration probe (drizzle-kit is blind to all of
-- them; `bun run db:generate` afterwards reports "No schema changes").
--
-- Additive: one new tenant-scoped table, and two CHECKs widened. No data is
-- rewritten — no pre-flight, no fail-fast. No foreign keys
-- (IMPLEMENTATION-GUIDE §3). The trusted signal is a signed device cookie
-- (design review A1), so there is no trusted-address table.
--
-- Lock cost (design review A18): re-adding `sessions_revoked_reason_check`
-- takes a brief ACCESS EXCLUSIVE lock on `sessions` and scans it, as 0075
-- and 0077 did — the table holds live sessions plus those ended within 30
-- days (the purge). `email_messages_template_check` the same on
-- `email_messages`, whose final rows are purged at 90 days. Both accepted at
-- deploy; every existing row already satisfies the narrower vocabulary.
CREATE TABLE "password_resets" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"user_id" uuid NOT NULL,
	"secret_hash" text NOT NULL,
	"requested_ip" text NOT NULL,
	"email_message_id" uuid,
	"code_failures" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"consumed_at" timestamp with time zone
);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "password_resets_user_created_idx" ON "password_resets" USING btree ("tenant_id","user_id","created_at");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "password_resets_expires_at_idx" ON "password_resets" USING btree ("expires_at");--> statement-breakpoint
-- ── hand-amended: the token's CHECKs ──────────────────────────────────────
-- A token always expires after it was made; wrong codes tried on its page
-- count 0..5 (the 5th spends it — `second-factor.ts` settleWrongResetCode).
ALTER TABLE "password_resets" ADD CONSTRAINT "password_resets_expiry_check" CHECK ("expires_at" > "created_at");--> statement-breakpoint
ALTER TABLE "password_resets" ADD CONSTRAINT "password_resets_code_failures_check" CHECK ("code_failures" >= 0 AND "code_failures" <= 5);--> statement-breakpoint
-- ── hand-amended: RLS — the uniform tenant policy ─────────────────────────
ALTER TABLE "password_resets" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "password_resets_tenant_isolation" ON "password_resets"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
-- ── hand-amended: the session revoke reasons gain `password-reset` ────────
-- 0077's two clauses kept verbatim (A18). Pinned against
-- `SESSION_REVOKE_REASONS` (modules/tenancy/sessions.ts) by test/sessions.spec.ts.
ALTER TABLE "sessions" DROP CONSTRAINT "sessions_revoked_reason_check";--> statement-breakpoint
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_revoked_reason_check" CHECK (
	("revoked_at" IS NULL) = ("revoked_reason" IS NULL)
	AND ("revoked_reason" IS NULL OR "revoked_reason" IN (
		'signed-out', 'deactivated', 'role-changed', 'client-suspended', 'refresh-reuse', 'released', 'device-revoked',
		'second-factor-reset', 'second-factor-changed', 'client-departed', 'password-reset'
	))
);--> statement-breakpoint
-- ── hand-amended: the mail templates gain the two reset mails ─────────────
-- Pinned against `EMAIL_TEMPLATES` (modules/mail/mail-rules.ts) by test/mail.spec.ts.
ALTER TABLE "email_messages" DROP CONSTRAINT "email_messages_template_check";--> statement-breakpoint
ALTER TABLE "email_messages" ADD CONSTRAINT "email_messages_template_check" CHECK ("template" IN ('user-invite', 'password-reset', 'password-changed'));--> statement-breakpoint
-- ── the post-migration assertion (the 0064/0077/0089 model) ───────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction and must be
-- refused BY ITS NAMED CONSTRAINT (each violates only its target, so the
-- name-order evaluation cannot pick another).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) accepted shapes: a fresh token, one at five failures and spent; a
	-- session revoked `password-reset`; a mail of each new template.
	BEGIN
		INSERT INTO "password_resets" ("id","tenant_id","user_id","secret_hash","requested_ip","code_failures","expires_at","consumed_at")
		VALUES (gen_random_uuid(), t, u, 'h-0103-a', '203.0.113.7', 0, now() + interval '60 minutes', NULL),
		       (gen_random_uuid(), t, u, 'h-0103-b', '2001:db8::1', 5, now() + interval '60 minutes', now());
		INSERT INTO "sessions" ("id","tenant_id","user_id","kind","refresh_hash","idle_expires_at","absolute_expires_at","revoked_at","revoked_reason")
		VALUES (gen_random_uuid(), t, u, 'web', 'h-0103', now(), now(), now(), 'password-reset');
		INSERT INTO "email_messages" ("id","tenant_id","user_id","template","to_email","params","sealed_secret","status","next_attempt_at")
		VALUES (gen_random_uuid(), t, u, 'password-reset', 'a@example.in', '{}', 'v1:k:i:t:c', 'pending', now()),
		       (gen_random_uuid(), t, u, 'password-changed', 'a@example.in', '{}', NULL, 'pending', now());
		RAISE EXCEPTION USING ERRCODE = 'P0103', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation THEN
			RAISE EXCEPTION 'migration 0103: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0103' THEN
			NULL; -- the accepted shapes landed, and the sentinel rolled them back
	END;
	-- (2) refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'expires before it was made',
		'six code failures',
		'negative code failures',
		'unknown revoke reason',
		'revoked without a reason',
		'unknown template'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'expires before it was made' THEN 'password_resets_expiry_check'
			WHEN 'six code failures' THEN 'password_resets_code_failures_check'
			WHEN 'negative code failures' THEN 'password_resets_code_failures_check'
			WHEN 'unknown template' THEN 'email_messages_template_check'
			ELSE 'sessions_revoked_reason_check'
		END;
		BEGIN
			CASE probe
				WHEN 'expires before it was made' THEN
					INSERT INTO "password_resets" ("id","tenant_id","user_id","secret_hash","requested_ip","expires_at")
					VALUES (gen_random_uuid(), t, u, 'h', '203.0.113.7', now() - interval '1 second');
				WHEN 'six code failures' THEN
					INSERT INTO "password_resets" ("id","tenant_id","user_id","secret_hash","requested_ip","code_failures","expires_at")
					VALUES (gen_random_uuid(), t, u, 'h', '203.0.113.7', 6, now() + interval '60 minutes');
				WHEN 'negative code failures' THEN
					INSERT INTO "password_resets" ("id","tenant_id","user_id","secret_hash","requested_ip","code_failures","expires_at")
					VALUES (gen_random_uuid(), t, u, 'h', '203.0.113.7', -1, now() + interval '60 minutes');
				WHEN 'unknown revoke reason' THEN
					INSERT INTO "sessions" ("id","tenant_id","user_id","kind","refresh_hash","idle_expires_at","absolute_expires_at","revoked_at","revoked_reason")
					VALUES (gen_random_uuid(), t, u, 'web', 'h', now(), now(), now(), 'password-changed');
				WHEN 'revoked without a reason' THEN
					INSERT INTO "sessions" ("id","tenant_id","user_id","kind","refresh_hash","idle_expires_at","absolute_expires_at","revoked_at","revoked_reason")
					VALUES (gen_random_uuid(), t, u, 'web', 'h', now(), now(), now(), NULL);
				WHEN 'unknown template' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at")
					VALUES (gen_random_uuid(), t, 'password-expired', 'a@example.in', '{}', 'pending', now());
			END CASE;
		EXCEPTION WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0103: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "password_resets" WHERE "tenant_id" = t)
	   OR EXISTS (SELECT 1 FROM "sessions" WHERE "tenant_id" = t)
	   OR EXISTS (SELECT 1 FROM "email_messages" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0103: a probe row survived.';
	END IF;
END $$;
